    for (Part p : inOrder) {
        sum = sum.add(p.amount());
        if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum), p.on(), taxRate)) {
            return p.on();
        }
    }
    return null;
}

